    p2.evaluate("MyRanch.go('decide')"); p2.click('.seg-btn[data-dec="drought"]'); p2.wait_for_timeout(1500)
    t=p2.inner_text('#dec_drMonitor')
    check('drought tab shows this week\'s Drought Monitor', p2.is_visible('#dec_drMonitor') and 'D2' in t, t)
    check('suggests forage lost from the soil survey unfavorable year', '36% of forage lost' in t, t)
    p2.click('#dr_useDm'); p2.wait_for_timeout(1200)
    import datetime
    check('use button sets forage lost and start month', p2.input_value('#dr_cut')=='36' and p2.evaluate("MyRanch.state().herd.dr.from")==datetime.date.today().month-1 and 'in use' in p2.inner_text('#dec_drMonitor').lower())
    # drought: scenario grid (forage lost x months), breakpoints, click a cell
    pg.evaluate("document.querySelector('[data-example=central-texas-1600ac]').click()"); pg.wait_for_timeout(2000)
    pg.evaluate("MyRanch.go('decide')"); pg.click('.seg-btn[data-dec="drought"]'); pg.wait_for_timeout(2500)
    check('drought grid: 3 severities x 4 lengths', pg.locator('#dec_drGrid td.dg').count()==12)
    dt=pg.inner_text('#dec_drOptions')
    check('drought: selling cows counts the vet & medicine they take with them', 'Other costs saved' in dt and '× $35' in dt, dt[:400])
    pg.fill('#dr_hayPrice','350'); pg.wait_for_timeout(3000)
    bt=pg.inner_text('#dec_drBreak')
    check('drought breakpoints: how long before selling pays, and the hay price', 'pays once the drought lasts' in bt and 'hay costs more than' in bt, bt)
    check('drought: at $350 hay a long severe drought favors selling', 'Sell 30%' in pg.inner_text('#dec_drGrid td.dg >> nth=11'))
    t0=pg.inner_text('#dec_drGrid td.dg >> nth=0'); check('drought: at $350 hay a short mild drought favors buying feed or weaning early, not selling cows', ('Buy feed' in t0 or 'Wean early' in t0 or 'about the same' in t0) and 'Sell' not in t0, t0)
    pg.click('#dec_drGrid [data-cut="75"][data-mo="9"]'); pg.wait_for_timeout(3000)
    check('drought: clicking a cell shows that drought in detail', pg.input_value('#dr_cut')=='75' and pg.input_value('#dr_months')=='9' and '75% less forage' in pg.inner_text('#dec_drText'))
    check('drought: 10-year part hidden for now', not pg.is_visible('#dr_longWrap') and pg.locator('#dec_drLongTable tbody tr').count()==0)
    check('drought: cows still owned counted at cull value', 'cows still owned' in pg.inner_text('#dec_drOptions').lower())
    # nursing calf growth predicted (NRC 2016 milk + Tedeschi & Fox RNS Eq. 13.20 calf forage and Table 13.6 milk energy + NRC 2016 growth)
    T=pg.evaluate("MyRanch.FEED.T67")
    check('NRC 1987 Table 6-7 coefficients kept for reference', T[0]==[35.6,-3.11] and T[3]==[17.9,-1.71] and T[6]==[22.4,-2.6], T)
    fox=pg.evaluate("""(()=>{var t=[],k;for(k=0;k<12;k++)t.push(2.5/0.82/4.409*100);
      var c=MyRanch.FEED.calfCurve({breed:'angus',cowLb:531*2.2046,birthLb:36*2.2046,peakMilkLb:8.17*2.2046,replRate:0},{day:0,weanAge:245},t);
      return [30,61,91,122,152,183,213,244].map(function(d){return c.bw[d]/2.2046;});})()""")
    ref=[71,104,134,162,189,217,246,281]
    check('RNS Table 13.2 (Fox 1988: frame-5 cow, 8.17 kg peak milk, 69% TDN): every month within 12%', all(abs(a/b-1)<0.12 for a,b in zip(fox,ref)), [round(x) for x in fox])
    tdn=pg.evaluate("MyRanch.FEED.QUALITY.range.map(function(q){return q[0]})")
    check('typical range: winter as before, April-October 5 points higher (diet selected, Vallentine; B-6124)', tdn[0]==48 and tdn[4]==67 and tdn[10]==50 and pg.evaluate("MyRanch.FEED.RANGE_SHAPE[4][0]")==62, tdn)
    cw=pg.evaluate("t=>MyRanch.FEED.calfCurve({breed:'angus',cowLb:1200,birthLb:68,peakMilkLb:18,replRate:30},{day:91,weanAge:200},t).wean", tdn)
    vw=pg.evaluate("t=>MyRanch.FEED.calfCurve({breed:'angus',cowLb:1000,birthLb:68,peakMilkLb:18,replRate:10},{day:121,weanAge:170},t).wean", tdn)
    check('SPA closeouts at moderate milk: predicted under the records (Cowden 563, Vanzandt 426) but within 30%', 563*0.7 < cw < 563 and 426*0.7 < vw < 426*1.02, (round(cw), round(vw)))
    cv=pg.evaluate("t=>{var c=MyRanch.FEED.calfCurve({breed:'angus',cowLb:1200,birthLb:68,peakMilkLb:18,replRate:0},{day:91,weanAge:200},t); return [c.forDm[10],c.forDm[100],c.forDm[190],c.adg[30],c.adg[190]]}", tdn)
    check('calves eat little grass early and more later', cv[0] < cv[1] < cv[2], cv)
    pg.evaluate("document.querySelector('[data-example=rolling-plains-154-cows]').click()"); pg.wait_for_timeout(2000)
    pg.evaluate("MyRanch.go('herd')"); pg.wait_for_timeout(500)
    F=pg.evaluate("(()=>{var f=MyRanch.feed(); return [f.calves.growth, f.econ.avgWeanLb, f.econ.creepLb]})()")
    check('predicted growth is the default: no creep, weaning from milk and grass', F[0]=='nrc' and F[2]==0 and 340 < F[1] < 500, F)
    check('herd step says the weight is predicted and compares the records', 'Predicted' in pg.evaluate("document.getElementById('fc_calfGrowth').selectedOptions[0].text") and 'Ruminant Nutrition System' in pg.evaluate("document.getElementById('fc_calfGrowthHint').textContent") and 'Your records vs. predicted' in pg.evaluate("document.getElementById('fc_weanLbHint').textContent") and pg.evaluate("document.getElementById('fc_calfShortSet').hidden"))
    # match the milk to the ranch's own weaning weight
    pg.evaluate("Object.assign(MyRanch.state().herd,{weanLb:470}); MyRanch.go('herd')"); pg.fill('#hd_cows','153'); pg.wait_for_timeout(300); pg.fill('#hd_cows','154'); pg.wait_for_timeout(900)
    pg.evaluate("document.getElementById('fc_matchMilk').click()"); pg.wait_for_timeout(1500)
    M=pg.evaluate("(()=>{var h=MyRanch.state().herd; return [h.milk, h.milkLb, MyRanch.feed().econ.avgWeanLb, document.getElementById('fc_milk').selectedOptions[0].text, document.getElementById('fc_weanLbHint').textContent]})()")
    check('"Match it" sets the milk so the predicted weaning weight is the one entered', M[0]=='custom' and 18 < M[1] < 40 and abs(M[2]/470-1) < 0.02 and 'Matched to my weaning weight' in M[3] and 'Milk set to' in M[4], M)
    pg.evaluate("var e=document.getElementById('fc_milk'); e.value='moderate'; e.dispatchEvent(new Event('change'))"); pg.wait_for_timeout(600)
    check('back to moderate milk lowers it again', pg.evaluate("MyRanch.feed().econ.avgWeanLb") < M[2] - 10)
    pg.evaluate("var e=document.getElementById('fc_calfGrowth'); e.value='target'; e.dispatchEvent(new Event('change'))"); pg.wait_for_timeout(800)
    F2=pg.evaluate("(()=>{var f=MyRanch.feed(); return [f.calves.growth, f.econ.avgWeanLb]})()")
    check('"I enter it" uses the weight entered', F2[0]=='target' and not pg.evaluate("document.getElementById('fc_calfShortSet').hidden"), F2)
    check('no JS errors', not errs, errs)
    b.close()
